def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    barrier = next(r for r, row in enumerate(g)
                   if len(set(row)) == 1 and row[0] not in (0, 5))
    background = g[0][0]
    rows = [r for r in range(barrier)
            if any(v != background for v in g[r])]
    top, bottom = min(rows), max(rows)

    # The object falls one row if there's room, leaving an 8 stripe at its
    # original top edge. Otherwise the stripe is drawn just above it.
    if bottom + 1 < barrier:
        for r in range(bottom, top - 1, -1):
            for c in range(w):
                if g[r][c] != background:
                    g[r + 1][c] = g[r][c]
                    g[r][c] = background
        g[top] = [8] * w
    else:
        g[top - 1] = [8] * w
    return g
